import { expect, test } from "nsh/test";
import { formatTime, normalizeClips, parseSearch, parseTime, sortClips, titleKey } from "./model";

const source = { kind: "movie" as const, id: 42 };
const raw = (key: string, name: string, published_at: string, official = true) => ({ id: name, site: "YouTube", key, name, published_at, official, type: "Clip" });

test("keeps valid YouTube associations, deduplicates and preserves title identity", () => {
  const clips = normalizeClips([
    raw("aqz-KE-bpKQ", "Unofficial", "2020-01-01", false),
    raw("aqz-KE-bpKQ", "Official", "2020-01-01"),
    { ...raw("ScMzIvxBSi4", "Other site", "2020-01-01"), site: "Vimeo" },
    raw("invalid", "Bad ID", "2020-01-01")
  ], source);
  expect(clips.length).toBe(1);
  expect(clips[0].name).toBe("Official");
  expect(titleKey(clips[0].source)).toBe("movie:42");
  expect(titleKey({ kind: "tv", id: 42 })).toBe("tv:42");
});

test("sorts publications oldest first with undated entries last", () => {
  const clips = normalizeClips([raw("aqz-KE-bpKQ", "Later", "2024-01-01"), raw("ScMzIvxBSi4", "Earlier", "2020-01-01"), raw("M7lc1UVf-VE", "Undated", "bad")], source);
  expect(sortClips(clips, "published", {}).map((clip) => clip.name)).toEqual(["Earlier", "Later", "Undated"]);
});

test("story positions override publications without assigning unknown positions", () => {
  const clips = normalizeClips([raw("aqz-KE-bpKQ", "Early upload", "2020-01-01"), raw("ScMzIvxBSi4", "Late upload", "2024-01-01"), raw("M7lc1UVf-VE", "Unplaced", "2010-01-01")], source);
  const positions = { "movie:42": { "aqz-KE-bpKQ": { seconds: 120 }, "ScMzIvxBSi4": { seconds: 0 } }, "tv:42": { "M7lc1UVf-VE": { seconds: 10 } } };
  expect(sortClips(clips, "story", positions).map((clip) => clip.name)).toEqual(["Late upload", "Early upload", "Unplaced"]);
});

test("parses IDs and keeps movie and TV namespaces distinct", () => {
  expect(parseSearch("tt0816692")).toEqual({ type: "imdb", id: "tt0816692" });
  expect(parseSearch("movie:157336")).toEqual({ type: "tmdb", ref: { kind: "movie", id: 157336 } });
  expect(parseSearch("https://www.themoviedb.org/tv/42-title")).toEqual({ type: "tmdb", ref: { kind: "tv", id: 42 } });
  expect(parseSearch("https://evil.example/movie/42").type).toBe("text");
});

test("parses precise story timecodes and rejects invalid positions", () => {
  expect(parseTime("01:02:03")).toBe(3723);
  expect(parseTime("12:34")).toBe(754);
  expect(parseTime("00:00")).toBe(0);
  expect(parseTime("01:99")).toBe(null);
  expect(parseTime("-01:30")).toBe(null);
  expect(formatTime(3723)).toBe("01:02:03");
});

import {expect,test} from 'nsh/test';
import {searchScenes,type SearchBackend} from './search';
import type {Candidate} from './model';
const title={kind:'movie' as const,id:157336,title:'Interstellar',originalTitle:'Interstellar',date:'2014-11-05',overview:'',poster:null,backdrop:null,rating:8};
const candidate=(id:string,name:string):Candidate=>({id,title:name,channel:'Uploader',description:'',duration:120,provider:'yt-dlp',identity:'review'});
test('searches opening, middle and ending uploads, expands playlists, and publishes progressively',async()=>{
 const queries:string[]=[],published:number[]=[];
 const backend:SearchBackend={
  videos:async(query)=>{queries.push(query);return [candidate('aqz-KE-bpKQ',query.includes('opening')?'Interstellar (2014) Opening Scene':'Interstellar (2014) Movie Scene'),candidate('ScMzIvxBSi4','Interstellar (2014) Trailer')];},
  playlists:async()=>['PLvalid123'],
  playlist:async()=>[candidate('M7lc1UVf-VE','Interstellar (2014) Ending Scene (10/10)')]
 };
 const result=await searchScenes(title,backend,{onProgress:value=>published.push(value.items.length)});
 expect(queries.some(query=>query.includes('opening'))).toBe(true);
 expect(queries.some(query=>query.includes('ending'))).toBe(true);
 expect(result.items.map(item=>item.id).sort()).toEqual(['M7lc1UVf-VE','aqz-KE-bpKQ'].sort());
 expect(published.length>1).toBe(true);
 const next=await searchScenes(title,backend,{searched:result.searched});
 expect(next.searched.some(query=>result.searched.includes(query))).toBe(false);
});
test('uses unique timed dialogue in uncovered runtime sections, without inventing placements',async()=>{
 const queries:string[]=[];
 const result=await searchScenes(title,{videos:async(query)=>{queries.push(query);return [candidate('aqz-KE-bpKQ','Interstellar (2014) Movie Scene')];}},{
  runtime:600,reference:[{start:10,end:14,text:'We have to leave this planet before the morning comes'},{start:590,end:595,text:'Now we can finally return to the people we love'}],
  cuts:[{start:0,end:500,videoId:'ScMzIvxBSi4'},{start:500,end:600}]
 });
 expect(queries.some(query=>query.includes('"now we can finally return'))).toBe(true);
 expect(queries.some(query=>query.includes('"we have to leave'))).toBe(false);
 expect(result.items[0].identity).toBe('likely');
});
test('keeps partial search results and retries failed queries, but fails if every source failed',async()=>{
 let calls=0;
 const backend={videos:async()=>{if(calls++>0)throw new Error('Unavailable');return [candidate('aqz-KE-bpKQ','Interstellar Scene')];}};
 const result=await searchScenes(title,backend);
 expect(result.items.length).toBe(1);
 expect(result.searched.length).toBe(1);
 expect(result.failed>0).toBe(true);
});
test('keeps episode timelines separate even when search returns the same series title',async()=>{
 const tv={...title,kind:'tv' as const,season:2,episode:8};
 const result=await searchScenes(tv,{videos:async()=>[
  candidate('aqz-KE-bpKQ','Interstellar S02E08 Ending Scene'),
  candidate('M7lc1UVf-VE','Interstellar S01E08 Ending Scene'),
  candidate('ScMzIvxBSi4','Interstellar Ending Scene')
 ]});
 expect(result.items.map(item=>item.id)).toEqual(['aqz-KE-bpKQ']);
});
test('cancelling a search prevents late candidates from being published',async()=>{
 const controller=new AbortController();let published=0,rejected=false;
 try{await searchScenes(title,{videos:async()=>{controller.abort();return [candidate('aqz-KE-bpKQ','Interstellar Scene')];}},{onProgress:()=>published++},controller.signal);}catch{rejected=true;}
 expect(rejected).toBe(true);expect(published).toBe(0);
});

import { expect, test } from "nsh/test";
import { buildCut, coveredSeconds, rankCandidate, sequenceOf, type Candidate, type Placement } from "./model";
import { alignTranscript, indexReference, parseSubtitles } from "./alignment";
const candidate=(id:string,title="Interstellar (2014) Movie Scene"):Candidate=>({id,title,channel:"Uploader",description:"",duration:120,provider:"manual",identity:"review"});
const range=(videoId:string,movieStart:number,videoStart:number,videoEnd:number):Placement=>({videoId,movieStart,videoStart,videoEnd,state:"confirmed",method:"manual"});

test("rejects promotional uploads and different releases while keeping scene candidates",()=>{
 expect(rankCandidate(candidate("aqz-KE-bpKQ"),"Interstellar","Interstellar","2014")?.identity).toBe("likely");
 for(const title of ["Interstellar (2014) Official Trailer","Interstellar reaction scene","Interstellar (2020) Movie Scene","Another Movie scene"])
  expect(rankCandidate(candidate("aqz-KE-bpKQ",title),"Interstellar","Interstellar","2014")).toBe(null);
 expect(sequenceOf("Interstellar (3/10) Movie CLIP")).toEqual({index:3,total:10});
});

test("unions overlaps, inserts runtime gaps and trims source offsets",()=>{
 const candidates=[candidate("aqz-KE-bpKQ"),candidate("ScMzIvxBSi4")];
 const cut=buildCut(300,[range("aqz-KE-bpKQ",30,10,110),range("ScMzIvxBSi4",100,0,100)],candidates);
 expect(coveredSeconds(cut)).toBe(170);
 expect(cut[0]).toEqual({start:0,end:30});
 expect(cut[1]).toMatchObject({start:30,end:130,videoId:"aqz-KE-bpKQ",videoStart:10,videoEnd:110});
 expect(cut[2]).toMatchObject({start:130,end:200,videoId:"ScMzIvxBSi4",videoStart:30,videoEnd:100});
 expect(cut[3]).toMatchObject({start:200,end:300});
});

test("proposed and missing-video ranges cannot claim coverage",()=>{
 const cut=buildCut(300,[{...range("aqz-KE-bpKQ",0,0,100),state:"proposed"},range("ScMzIvxBSi4",150,0,100)],[candidate("aqz-KE-bpKQ")]);
 expect(coveredSeconds(cut)).toBe(0);
 expect(cut).toEqual([{start:0,end:300}]);
});

const srt=`1\n00:10:01,000 --> 00:10:04,000\nWe need to cross the frozen river before sunrise.\n\n2\n00:10:06,000 --> 00:10:09,000\nThe old bridge has been gone for twenty years.\n\n3\n00:10:12,000 --> 00:10:15,000\nThen we shall find another way through the valley.\n\n4\n00:10:19,000 --> 00:10:22,000\nKeep the lantern steady and follow my footsteps.\n`;
const clip=srt.replaceAll("00:10:","00:00:");

test("aligns timed clip dialogue to movie subtitles and proposes a bounded source range",()=>{
 const reference=indexReference(parseSubtitles(srt));
 const match=alignTranscript(reference,parseSubtitles(clip),"aqz-KE-bpKQ",30,1000);
 expect(match).toMatchObject({movieStart:601,videoStart:1,videoEnd:22,state:"proposed",method:"transcript",anchors:4});
});

test("rejects unrelated and ambiguous repeated dialogue",()=>{
 const reference=indexReference(parseSubtitles(srt));
 const other=parseSubtitles(clip.replace(/We need[^\n]*|The old[^\n]*|Then we[^\n]*|Keep the[^\n]*/g,"These words belong to a completely unrelated television programme."));
 expect(alignTranscript(reference,other,"aqz-KE-bpKQ",30,1000)).toBe(null);
 const twice=[...parseSubtitles(srt),...parseSubtitles(srt).map(cue=>({...cue,start:cue.start+100,end:cue.end+100}))];
 expect(alignTranscript(indexReference(twice),parseSubtitles(clip),"aqz-KE-bpKQ",30,1000)).toBe(null);
});

test("reads WebVTT timing and rejects untimed text",()=>{
 expect(parseSubtitles("WEBVTT\n\n00:01.000 --> 00:03.000\nA short cue.")[0]).toMatchObject({start:1,end:3});
 expect(()=>parseSubtitles("No timecodes here")).toThrow("timecodes");
});

test("coverage cannot extend beyond the actual source clip duration",()=>{
 const cut=buildCut(1000,[range("aqz-KE-bpKQ",100,10,900)],[candidate("aqz-KE-bpKQ")]);
 expect(coveredSeconds(cut)).toBe(110);
 expect(cut.find(item=>item.videoId)?.videoEnd).toBe(120);
});

test("assembles video ranges across providers while excluding audio and live streams",()=>{
 const vimeo:Candidate={...candidate("vimeo:76979871"),source:{provider:"vimeo",id:"76979871",url:"https://vimeo.com/76979871",kind:"video"}};
 const audio:Candidate={...candidate("spotify:track:4uLU6hMCjMI75M1A2tKUQC"),source:{provider:"spotify",id:"track:4uLU6hMCjMI75M1A2tKUQC",url:"https://open.spotify.com/track/4uLU6hMCjMI75M1A2tKUQC",kind:"audio"}};
 const live:Candidate={...candidate("twitch:channel:monstercat"),source:{provider:"twitch",id:"channel:monstercat",url:"https://www.twitch.tv/monstercat",kind:"live"}};
 const cut=buildCut(300,[range("aqz-KE-bpKQ",0,0,60),range(vimeo.id,60,0,60),range(audio.id,120,0,60),range(live.id,180,0,60)],[candidate("aqz-KE-bpKQ"),vimeo,audio,live]);
 expect(coveredSeconds(cut)).toBe(120);
 expect(cut[1]).toMatchObject({videoId:vimeo.id,start:60,end:120});
 expect(cut[2]).toEqual({start:120,end:300});
});

