import {year,type Media} from '../tmdb/model';
import {normalize,rankCandidate,type Candidate,type Cue,type Cut} from './model';

/** Providers supply metadata; this module owns identity, breadth and gap-directed search. */
export interface SearchBackend {
  videos(query:string,signal?:AbortSignal):Promise<Candidate[]>;
  playlists?(query:string,signal?:AbortSignal):Promise<string[]>;
  playlist?(id:string,signal?:AbortSignal):Promise<Candidate[]>;
}
export interface SearchProgress {items:Candidate[];searched:string[];scanned:number;failed:number}
export interface SearchContext {
  aliases?:string[];searched?:string[];reference?:Cue[];cuts?:Cut[];runtime?:number;
  onProgress?:(progress:SearchProgress)=>void;
}
const quoted=(text:string)=>`"${text.replace(/["\r\n]/g,' ').trim()}"`;
function sameEpisode(candidate:Candidate,title:Media) {
  if(title.episode===undefined)return true;
  const text=`${candidate.title} ${candidate.description}`;
  const markers=[...text.matchAll(/\bS(\d{1,2})\s*E(\d{1,3})\b|\bseason\s*(\d{1,2})\D{0,20}episode\s*(\d{1,3})\b|\b(\d{1,2})x(\d{2,3})\b/gi)];
  return markers.length>0&&markers.every(marker=>Number(marker[1]??marker[3]??marker[5])===title.season&&Number(marker[2]??marker[4]??marker[6])===title.episode);
}
function plan(title:Media,context:SearchContext) {
  const aliases=[...new Set([title.title,title.originalTitle,...context.aliases??[]].filter(Boolean))].slice(0,4);
  const date=title.kind==='movie'?year(title.date):'';
  const scope=title.episode!==undefined?` S${String(title.season).padStart(2,'0')}E${String(title.episode).padStart(2,'0')}`:'';
  const identity=`${quoted(title.title)} ${date}${scope}`.trim();
  const gaps=(context.cuts??[{start:0,end:context.runtime??0}]).filter(cut=>!cut.videoId&&cut.end-cut.start>=8);
  const phrases=new Set<string>();
  const dialogue:string[]=[];
  // Sample each missing section across its duration, including beginning and end.
  for(const fraction of [0,1,0.25,0.5,0.75]) for(const gap of gaps) {
    const target=gap.start+(gap.end-gap.start)*fraction;
    const cues=(context.reference??[]).filter(cue=>cue.start>=gap.start&&cue.end<=gap.end&&normalize(cue.text).split(' ').length>=7);
    const cue=cues.sort((a,b)=>Math.abs(a.start-target)-Math.abs(b.start-target))[0];
    if(!cue)continue;
    const phrase=normalize(cue.text).split(' ').slice(0,11).join(' ');
    // A phrase repeated in the reference cannot distinguish its scene.
    if(phrases.has(phrase)||(context.reference??[]).filter(item=>normalize(item.text).includes(phrase)).length!==1)continue;
    phrases.add(phrase);dialogue.push(`${identity} ${quoted(phrase)}`);
  }
  const queries=[...dialogue.slice(0,3),`${identity} movie scene`,`${identity} opening scene`,`${identity} ending scene`,`${identity} movieclips`,`${identity} best scenes`,`${identity} scene 1/10`,...dialogue.slice(3)];
  for(const alias of aliases) for(const suffix of ['clip','full scene','first scene','final scene','movie clip 4K','part scene','all scenes','opening credits','closing scene'])
    queries.push(`${quoted(alias)} ${date}${scope} ${suffix}`.trim());
  return [...new Set(queries)].filter(query=>!(context.searched??[]).includes(query));
}

/** Two concurrent requests, six fresh queries and two related playlists per pass. */
export async function searchScenes(title:Media,backend:SearchBackend,context:SearchContext={},signal?:AbortSignal):Promise<SearchProgress> {
  const queries=plan(title,context).slice(0,6);
  const items=new Map<string,Candidate>(),searched:string[]=[];
  let scanned=0,failed=0,cursor=0;
  const result=():SearchProgress=>({items:[...items.values()].sort((a,b)=>(b.score??0)-(a.score??0)||a.id.localeCompare(b.id)),searched:[...searched],scanned,failed});
  const publish=(candidates:Candidate[])=>{
    if(signal?.aborted)throw new Error('Cancelled');
    scanned+=candidates.length;
    for(const candidate of candidates) {
      if(!sameEpisode(candidate,title))continue;
      const ranked=rankCandidate(candidate,title.title,title.originalTitle,title.kind==='movie'?year(title.date):'',context.aliases);
      if(ranked)items.set(ranked.id,ranked);
    }
    context.onProgress?.(result());
  };
  const worker=async()=>{
    while(cursor<queries.length&&!signal?.aborted) {
      const query=queries[cursor++];
      try {const rows=await backend.videos(query,signal);if(signal?.aborted)throw new Error('Cancelled');searched.push(query);publish(rows);}
      catch(error){if(signal?.aborted)throw error;failed++;}
    }
  };
  await Promise.all([worker(),worker()]);
  if(signal?.aborted)throw new Error('Cancelled');
  if(queries.length&&!searched.length)throw new Error('Clip search is unavailable. Check yt-dlp or change the provider.');
  if(backend.playlists&&backend.playlist&&queries.length) {
    const key=`playlist:${quoted(title.title)} ${title.episode!==undefined?`S${String(title.season).padStart(2,'0')}E${String(title.episode).padStart(2,'0')}`:year(title.date)} movie clips`;
    if(!(context.searched??[]).includes(key))try {
      const ids=await backend.playlists(key.slice(9),signal);
      let expanded=true;
      for(const id of [...new Set(ids)].slice(0,2))try {publish(await backend.playlist(id,signal));}catch(error){if(signal?.aborted)throw error;failed++;expanded=false;}
      if(expanded)searched.push(key);
    }catch(error){if(signal?.aborted)throw error;failed++;}
  }
  context.onProgress?.(result());
  return result();
}

export type MediaKind = "movie" | "tv";
export interface TitleRef { kind: MediaKind; id: number; season?: number; episode?: number }
export interface Media extends TitleRef {
  title: string; originalTitle: string; date: string; overview: string;
  poster: string | null; backdrop: string | null; rating: number;
}
export interface Clip {
  id: string; youtubeId: string; name: string; type: string; official: boolean;
  publishedAt: string; language: string; source: TitleRef;
}
export interface TitleDetail extends Media {
  aliases?:string[]; imdbId: string | null; runtime: number | null; genres: string[]; clips: Clip[];
  seasons: { number: number; name: string }[];
  episodes: { number: number; name: string; date: string }[];
}
export interface Page { items: Media[]; page: number; totalPages: number; total: number }
export interface Position { seconds: number }
export type Positions = Record<string, Record<string, Position>>;
export type ClipOrder = "published" | "story";

export const titleKey = (ref: TitleRef) => `${ref.kind}:${ref.id}${ref.season !== undefined ? `:s${ref.season}` : ""}${ref.episode !== undefined ? `:e${ref.episode}` : ""}`;
export const titlePath = (ref: TitleRef) => `${ref.kind}/${ref.id}${ref.season !== undefined ? `/season/${ref.season}` : ""}${ref.episode !== undefined ? `/episode/${ref.episode}` : ""}`;
export const year = (date: string) => /^\d{4}/.exec(date)?.[0] ?? "";
export function imageUrl(path: string | null, size = "w342") {
  return path && /^\/[\w.\/-]+$/.test(path) ? `https://image.tmdb.org/t/p/${size}${path}` : undefined;
}
export function parseTime(text: string): number | null {
  if (!/^\d{1,3}:\d{2}(?::\d{2})?$/.test(text.trim())) return null;
  const parts = text.trim().split(":").map(Number);
  if (parts.slice(1).some((value) => value > 59)) return null;
  const seconds = parts.length === 3 ? parts[0] * 3600 + parts[1] * 60 + parts[2] : parts[0] * 60 + parts[1];
  return seconds <= 604800 ? seconds : null;
}
export function formatTime(seconds: number) {
  seconds = Math.max(0, Math.floor(seconds));
  return `${Math.floor(seconds / 3600).toString().padStart(2, "0")}:${Math.floor(seconds % 3600 / 60).toString().padStart(2, "0")}:${Math.floor(seconds % 60).toString().padStart(2, "0")}`;
}

/** Only server-attached YouTube videos belong to this exact media/scope. */
export function normalizeClips(raw: unknown, source: TitleRef): Clip[] {
  if (!Array.isArray(raw)) return [];
  const byKey = new Map<string, Clip>();
  for (const value of raw) {
    if (!value || value.site !== "YouTube" || typeof value.key !== "string" || !/^[\w-]{11}$/.test(value.key)) continue;
    const clip: Clip = {
      id: typeof value.id === "string" ? value.id : value.key,
      youtubeId: value.key, name: typeof value.name === "string" ? value.name : "Video",
      type: typeof value.type === "string" ? value.type : "Video", official: value.official === true,
      publishedAt: typeof value.published_at === "string" && Number.isFinite(Date.parse(value.published_at)) ? value.published_at : "",
      language: typeof value.iso_639_1 === "string" ? value.iso_639_1 : "", source: { ...source }
    };
    const previous = byKey.get(clip.youtubeId);
    if (!previous || (clip.official && !previous.official) || (clip.official === previous.official && clip.id < previous.id)) byKey.set(clip.youtubeId, clip);
  }
  return [...byKey.values()];
}
export function positionOf(clip: Clip, positions: Positions): Position | undefined {
  return positions[titleKey(clip.source)]?.[clip.youtubeId];
}
export function sortClips(clips: Clip[], order: ClipOrder, positions: Positions): Clip[] {
  return [...clips].sort((a, b) => {
    if (order === "story") {
      const pa = positionOf(a, positions), pb = positionOf(b, positions);
      if (Boolean(pa) !== Boolean(pb)) return pa ? -1 : 1;
      if (pa && pb) {
        const episode = (a.source.season ?? 0) - (b.source.season ?? 0) || (a.source.episode ?? 0) - (b.source.episode ?? 0);
        if (episode || pa.seconds !== pb.seconds) return episode || pa.seconds - pb.seconds;
      }
    }
    const publication = (a.publishedAt ? Date.parse(a.publishedAt) : Infinity) - (b.publishedAt ? Date.parse(b.publishedAt) : Infinity);
    return (Number.isFinite(publication) && publication !== 0 ? publication : 0) ||
      (a.publishedAt ? 0 : 1) - (b.publishedAt ? 0 : 1) ||
      a.name.localeCompare(b.name) || a.youtubeId.localeCompare(b.youtubeId);
  });
}

export type SearchIdentity = { type: "tmdb"; ref: TitleRef } | { type: "imdb"; id: string } | { type: "text"; query: string };
export function parseSearch(input: string): SearchIdentity {
  const query = input.trim();
  if (/^tt\d{7,10}$/i.test(query)) return { type: "imdb", id: query.toLowerCase() };
  const direct = query.match(/^(movie|tv)[:/](\d+)$/i) ?? query.match(/^https:\/\/(?:www\.)?themoviedb\.org\/(movie|tv)\/(\d+)(?:-[\w-]+)?\/?(?:\?.*)?$/i);
  if (direct && Number.isSafeInteger(Number(direct[2])) && Number(direct[2]) > 0) return { type: "tmdb", ref: { kind: direct[1].toLowerCase() as MediaKind, id: Number(direct[2]) } };
  return { type: "text", query };
}

import {mediaCapabilities,type MediaSource} from "../media/source";
import type { TitleRef } from "../tmdb/model";
export interface Candidate {
  id: string; title: string; channel: string; description: string; duration: number;
  provider: "yt-dlp" | "invidious" | "manual"; identity: "likely" | "review";
  sequence?: { index: number; total: number };
  source?: MediaSource;
  score?: number;
}
export interface Cue { start: number; end: number; text: string }
export interface Placement {
  videoId: string; movieStart: number; videoStart: number; videoEnd: number;
  state: "proposed" | "confirmed"; method: "transcript" | "manual";
  anchors?: number; spread?: number;
}
export interface SceneBook {
  ref: TitleRef; candidates: Candidate[]; placements: Record<string, Placement>;
  reference?: string; runtime?: number; updatedAt: number;
  searches?: string[]; searchRevision?: number;
}
export interface Cut {
  start: number; end: number; videoId?: string; videoStart?: number; videoEnd?: number;
}
export const normalize = (text: string) => text.normalize("NFKD").replace(/[\u0300-\u036f]/g, "").toLowerCase().replace(/[^\p{L}\p{N}\p{M}]+/gu, " ").trim();
export function sequenceOf(title: string) {
  const match = title.match(/\(\s*(\d{1,3})\s*\/\s*(\d{1,3})\s*\)/);
  if (!match) return undefined;
  const index = Number(match[1]), total = Number(match[2]);
  return index > 0 && index <= total && total <= 100 ? { index, total } : undefined;
}
export function rankCandidate(candidate: Candidate, title: string, originalTitle: string, year: string, extraAliases: string[] = []): Candidate | null {
  const text = normalize(candidate.title), description = normalize(candidate.description);
  if (/\b(trailers?|teasers?|reviews?|reactions?|recaps?|explained|explanations?|analysis|soundtracks?|gameplay|fan edits?|fan made|full movies?|behind the scenes|making of|interviews?|featurettes?|bloopers|deleted scenes?|comparisons?|ai generated|ai recreated|lego|parody|parodies|crossovers?|theatre response|theater response|imax response|ending music|music video|mashups?|remakes?|re creations?)\b/.test(text)) return null;
  if (!Number.isFinite(candidate.duration) || candidate.duration < 15 || candidate.duration > 1800) return null;
  const aliases = [...new Set([title, originalTitle,...extraAliases].map(normalize).filter(Boolean))];
  const exactTitle = aliases.some((alias) => ` ${text} `.includes(` ${alias} `));
  // A description can list dozens of unrelated titles. It cannot establish identity.
  if (!exactTitle) return null;
  const primary = text.split(/\b(?:like|versus|vs|inspired by|similar to)\b/)[0];
  if (!aliases.some(alias=>` ${primary} `.includes(` ${alias} `))) return null;
  const years: string[] = candidate.title.match(/\b(?:19|20)\d{2}\b/g) ?? [];
  if (year && years.length && !years.includes(year)) return null;
  // “It”, “Up”, “Us”, etc. are ordinary words; require release evidence.
  if (aliases.every(alias=>alias.length<=3) && (!year || !years.includes(year))) return null;
  const scene = /\b(scene|clip|movieclips|ending|opening)\b/.test(text) || Boolean(sequenceOf(candidate.title));
  if (!scene) return null;
  const sequence=sequenceOf(candidate.title);
  const channel=normalize(candidate.channel);
  const score=40+(years.includes(year)?15:0)+(sequence?10:0)+(/\b(scene|clip)\b/.test(text)?10:0)+
    (/movieclips|paramount|warner bros|sony pictures|universal pictures|lionsgate|disney|20th century|mgm|a24|netflix/.test(channel)?15:0)+
    (aliases.some(alias=>` ${description} `.includes(` ${alias} `))?5:0);
  return { ...candidate, identity: "likely", sequence, score };
}

export const canPlaceCandidate = (candidate:Candidate) => (!candidate.source||mediaCapabilities(candidate.source).timeline)&&candidate.duration>0;
export const isYouTubeCandidate = (candidate:Candidate) => !candidate.source||candidate.source.provider==="youtube";

/** Exact, confirmed ranges only. Overlapping uploads never double-count time. */
export function buildCut(runtime: number, placements: Placement[], candidates: Candidate[]): Cut[] {
  if (!Number.isFinite(runtime) || runtime <= 0) return [];
  const durations = new Map(candidates.filter(canPlaceCandidate).map((candidate) => [candidate.id,candidate.duration]));
  const valid = placements.map((p)=>({...p,videoEnd:Math.min(p.videoEnd,durations.get(p.videoId)??0)})).filter((p) => p.state === "confirmed" && durations.has(p.videoId) &&
    [p.movieStart, p.videoStart, p.videoEnd].every(Number.isFinite) && p.movieStart >= 0 && p.videoStart >= 0 && p.videoEnd > p.videoStart);
  const end = (p: Placement) => Math.min(runtime, p.movieStart + p.videoEnd - p.videoStart);
  const points = [...new Set([0, runtime, ...valid.flatMap((p) => [Math.min(runtime, p.movieStart), end(p)])])].sort((a,b) => a-b);
  const cuts: Cut[] = [];
  for (let i=0; i<points.length-1; i++) {
    const start = points[i], finish = points[i+1];
    if (finish <= start) continue;
    const previousId = cuts[cuts.length-1]?.videoId;
    const eligible = valid.filter((p) => p.movieStart <= start && end(p) >= finish)
      .sort((a,b) => (a.method === "manual" ? 0 : 1) - (b.method === "manual" ? 0 : 1) ||
        (b.videoEnd-b.videoStart) - (a.videoEnd-a.videoStart) ||
        (a.videoId===previousId?0:1)-(b.videoId===previousId?0:1) || a.videoId.localeCompare(b.videoId));
    const selected = eligible[0];
    const cut: Cut = selected ? { start, end: finish, videoId: selected.videoId,
      videoStart: selected.videoStart + start-selected.movieStart, videoEnd: selected.videoStart + finish-selected.movieStart } : { start, end: finish };
    const previous = cuts[cuts.length-1];
    if (previous && previous.videoId === cut.videoId && previous.end === cut.start &&
      (!cut.videoId || previous.videoEnd === cut.videoStart)) { previous.end = finish; previous.videoEnd = cut.videoEnd; }
    else cuts.push(cut);
  }
  return cuts;
}
export const coveredSeconds = (cuts: Cut[]) => cuts.reduce((sum, cut) => sum + (cut.videoId ? cut.end-cut.start : 0), 0);

import {parseMediaSource,mediaKey,mediaCapabilities} from './source.ts';

/** Runs only inside WKWebView. The native app talks to this small transport. */
export function installBridge({provider,tag}) {
  const config=window.theaterConfig||{};
  const root=document.getElementById('player');
  let media=null, session=null, removeListeners=()=>{}, lastProgress=0, pendingPause=false;
  const fit=()=>{
    if(provider!=="tiktok"||!media||!root.getBoundingClientRect)return;
    const bounds=root.getBoundingClientRect(),scale=Math.min(bounds.width/325,bounds.height/578);
    if(scale>0){media.style.width="325px";media.style.height="578px";media.style.flexShrink="0";media.style.transform=`scale(${scale})`;}
  };
  const observer=typeof ResizeObserver!=="undefined"?new ResizeObserver(fit):null;
  observer?.observe(root);window.addEventListener("resize",fit);
  const report=(type,value,current=session)=>{
    window.nsh?.postMessage(JSON.stringify({type,value,provider,id:current?.id,request:current?.request}));
  };
  const matches=current=>{
    if(!current||session!==current||!media)return false;
    if(provider==='youtube'){
      const actual=media.engine?.getVideoData?.()?.video_id;
      if(actual&&actual!==current.source.id)return false;
    }
    return true;
  };
  const read=()=>({seconds:Number.isFinite(media?.currentTime)?media.currentTime:0,duration:Number.isFinite(media?.duration)?media.duration:0,muted:Boolean(media?.muted)});
  const fail=(error,current=session)=>{
    if(!current||current!==session)return;
    const code=error?.data?.youtubeErrorCode;
    report('error',{code:typeof code==='number'?code:undefined,message:String(error?.message||'Playback unavailable.').slice(0,500)},current);
  };
  const play=current=>{
    if(!matches(current))return;
    pendingPause=false;
    try{Promise.resolve(media.play()).catch(error=>{
      if(session!==current)return;
      if(error?.name==='NotAllowedError')report('blocked',true,current);else fail(error,current);
    });}catch(error){fail(error,current);}
  };
  const pause=()=>{pendingPause=true;try{media?.pause();}catch{}};
  const finish=current=>{
    if(!matches(current)||current.finished)return;
    current.finished=true;pause();report('state',0,current);
  };
  const metadata=current=>{
    if(!matches(current))return;
    if(!current.started&&media.readyState>=1){
      current.started=true;
      if(current.start>0&&current.caps.seek)try{media.currentTime=current.start;}catch{}
    }
    if(!current.started)return;
    const info=read();
    if(!current.hasMetadata||info.duration!==current.duration){current.hasMetadata=true;current.duration=info.duration;report('metadata',info,current);}
    if(pendingPause||current.paused)pause();
  };
  const progress=(current,force=false)=>{
    if(!matches(current)||!current.started)return;
    const info=read();
    if(current.end!==undefined&&info.seconds>=current.end){finish(current);return;}
    if(force||Date.now()-lastProgress>=250){lastProgress=Date.now();report('progress',info,current);}
  };
  const listen=current=>{
    const handlers={
      loadedmetadata:()=>metadata(current),durationchange:()=>metadata(current),loadcomplete:()=>metadata(current),
      playing:()=>{if(!matches(current)||current.finished)return;metadata(current);if(pendingPause||current.paused){pause();return;}report('state',1,current);},
      pause:()=>{if(matches(current)&&!current.finished)report('state',2,current);},
      waiting:()=>{if(matches(current))report('state',3,current);},
      ended:()=>finish(current),
      offline:()=>{if(matches(current))report("state",4,current);},
      online:()=>{if(matches(current))report("state",3,current);},
      timeupdate:()=>{metadata(current);progress(current);},
      volumechange:()=>progress(current,true),
      error:()=>{if(matches(current))fail(media.error,current);}
    };
    const target=media;
    for(const [type,handler]of Object.entries(handlers))target.addEventListener(type,handler);
    removeListeners=()=>{for(const [type,handler]of Object.entries(handlers))target.removeEventListener(type,handler);};
  };
  const load=command=>{
    const source=parseMediaSource(command.source?.url||'');
    if(!source||source.provider!==provider||command.id!==mediaKey(source)||!Number.isSafeInteger(command.request)||command.request<1)return;
    const caps=mediaCapabilities(source);
    const minimum=Number.isFinite(command.minimumSeconds)?Math.max(0,command.minimumSeconds):0;
    const start=Number.isFinite(command.startSeconds)?Math.max(minimum,command.startSeconds):minimum;
    const end=caps.timeline&&Number.isFinite(command.endSeconds)&&command.endSeconds>start?command.endSeconds:undefined;
    const previous=session;
    removeListeners();
    // YouTube can replace its source through its API without rebuilding the iframe.
    // Other providers get a fresh adapter so old asynchronous events cannot own a new clip.
    if(media&&(provider!=='youtube'||previous?.controls!==Boolean(config.controls))){
      try{media.pause();}catch{}
      media.remove();media=null;
    }
    const fresh=!media;
    if(fresh){
      media=document.createElement(tag);
      media.id='media';
      media.setAttribute('playsinline','');media.setAttribute('preload','metadata');
      media.setAttribute('referrerpolicy','strict-origin-when-cross-origin');
      if(config.controls||provider==='spotify')media.setAttribute('controls','');
    }
    media.autoplay=!command.paused;
    session={id:command.id,request:command.request,source,caps,minimum,start,end,paused:Boolean(command.paused),controls:Boolean(config.controls),finished:false,started:false,duration:0,hasMetadata:false};
    pendingPause=session.paused;lastProgress=0;
    listen(session);
    let url=source.url;
    if(provider==='youtube'){
      const link=new URL(url);link.searchParams.set('t',String(start));url=link.toString();
      media.source={src:url,engine:{youtube:{origin:config.origin,iv_load_policy:3,rel:0}}};
    }else if(provider==='twitch')media.source={src:url,engine:{twitch:{parent:[new URL(config.origin).hostname]}}};
    else media.source={src:url};
    if(fresh)root.appendChild(media);
    fit();
    report('capabilities',caps);report('state',3);
    // Equal URLs intentionally skip an adapter reload; a new range still needs to arm.
    metadata(session);
    if(!session.paused)play(session);
  };
  window.theater=command=>{
    if(!command||typeof command!=='object')return;
    if(command.type==='load'){load(command);return;}
    const current=session;
    if(!current||command.request!==current.request)return;
    if(command.type==='pause'){current.paused=true;pause();}
    else if(command.type==='toggle'){
      if(media.paused||current.finished){if(current.finished&&current.caps.seek)media.currentTime=current.start;current.paused=false;current.finished=false;play(current);}
      else{current.paused=true;pause();}
    }else if(command.type==='mute'&&current.caps.mute){try{media.muted=!media.muted;}catch(error){fail(error,current);}}
    else if(command.type==='seek'&&current.caps.seek&&Number.isFinite(command.seconds)){
      const max=current.end??(Number.isFinite(media.duration)&&media.duration>0?media.duration:Infinity);
      try{current.finished=false;media.currentTime=Math.max(current.minimum,Math.min(max,command.seconds));progress(current,true);}catch(error){fail(error,current);}
    }else if(command.type==='rate'&&current.caps.rate&&[0.5,0.75,1,1.25,1.5,2].includes(command.value)){
      try{media.playbackRate=command.value;}catch(error){fail(error,current);}
    }else if(command.type==='volume'&&current.caps.volume&&Number.isFinite(command.value)){
      try{media.volume=Math.max(0,Math.min(1,command.value));}catch(error){fail(error,current);}
    }
  };
  const timer=setInterval(()=>progress(session),100);
  window.addEventListener('pagehide',()=>{clearInterval(timer);observer?.disconnect();pause();removeListeners();});
  report('ready',true);
}

import type { Media, MediaKind, Page, TitleDetail, TitleRef } from "./model";
import { normalizeClips, parseSearch, titlePath } from "./model";

export const GUEST_BASE = "https://movies-proxy.vercel.app/tmdb";
export const TMDB_BASE = "https://api.themoviedb.org/3";
export interface Connection { mode: "guest" | "direct"; token: string }
type Raw = Record<string, any>;

export function normalizeMedia(raw: Raw, kind?: MediaKind): Media | null {
  if (!raw || typeof raw !== "object") return null;
  const mediaKind = kind ?? raw.media_type;
  if (!raw || !["movie", "tv"].includes(mediaKind) || !Number.isSafeInteger(raw.id) || raw.id <= 0 || raw.adult === true) return null;
  return { kind: mediaKind, id: raw.id, title: String(raw.title ?? raw.name ?? "Untitled"),
    originalTitle: String(raw.original_title ?? raw.original_name ?? raw.title ?? raw.name ?? "Untitled"),
    date: String(raw.release_date ?? raw.first_air_date ?? raw.air_date ?? ""), overview: String(raw.overview ?? ""),
    poster: typeof raw.poster_path === "string" ? raw.poster_path : null,
    backdrop: typeof raw.backdrop_path === "string" ? raw.backdrop_path : null,
    rating: typeof raw.vote_average === "number" ? raw.vote_average : 0 };
}
export class TmdbClient {
  constructor(private connection: Connection) {}
  async get(path: string, params: Record<string, string | number> = {}, signal?: AbortSignal): Promise<Raw> {
    const url = new URL(`${this.connection.mode === "guest" ? GUEST_BASE : TMDB_BASE}/${path}`);
    url.searchParams.set("language", "en-US");
    for (const [key, value] of Object.entries(params)) url.searchParams.set(key, String(value));
    const headers: Record<string, string> = { accept: "application/json" };
    if (this.connection.mode === "direct") {
      if (/^[a-f\d]{32}$/i.test(this.connection.token)) url.searchParams.set("api_key", this.connection.token);
      else headers.Authorization = `Bearer ${this.connection.token.replace(/^Bearer\s+/i, "")}`;
    }
    let response: Response;
    try { response = await fetch(url.toString(), { headers, signal }); }
    catch (error) { if (signal?.aborted) throw error; throw new Error("Can’t reach TMDB. Try again."); }
    if (!response.ok) {
      if (response.status === 401 || response.status === 403) throw new Error(this.connection.mode === "guest" ? "Guest access is unavailable. Try again or connect your TMDB token." : "TMDB rejected this token.");
      if (response.status === 404) throw new Error("Title not found.");
      if (response.status === 429) throw new Error("Too many requests. Try again shortly.");
      throw new Error("TMDB is unavailable. Try again.");
    }
    const data = await response.json();
    if (!data || typeof data !== "object" || data.success === false) throw new Error("TMDB returned an invalid response.");
    return data;
  }
  async browse(kind: "all" | MediaKind, query: string, page: number, signal?: AbortSignal): Promise<Page> {
    const identity = parseSearch(query);
    let data: Raw;
    if (query && identity.type === "tmdb") {
      const media = normalizeMedia(await this.get(titlePath(identity.ref), {}, signal), identity.ref.kind);
      return { items: media ? [media] : [], page: 1, totalPages: 1, total: media ? 1 : 0 };
    }
    if (query && identity.type === "imdb") {
      data = await this.get(`find/${identity.id}`, { external_source: "imdb_id" }, signal);
      if (!Array.isArray(data.movie_results) || !Array.isArray(data.tv_results)) throw new Error("TMDB returned an invalid list.");
      const items = [...(data.movie_results ?? []).map((raw: Raw) => normalizeMedia(raw, "movie")), ...(data.tv_results ?? []).map((raw: Raw) => normalizeMedia(raw, "tv"))].filter(Boolean) as Media[];
      return { items, page: 1, totalPages: 1, total: items.length };
    }
    data = query ? await this.get(`search/${kind === "all" ? "multi" : kind}`, { query, page, include_adult: "false" }, signal) :
      await this.get(`trending/${kind}/week`, { page }, signal);
    if (!Array.isArray(data.results)) throw new Error("TMDB returned an invalid list.");
    const items = data.results.map((raw: Raw) => normalizeMedia(raw, kind === "all" ? undefined : kind)).filter(Boolean) as Media[];
    return { items, page: Number(data.page ?? page), totalPages: Math.min(500, Number(data.total_pages ?? 1)), total: Number(data.total_results ?? items.length) };
  }
  async detail(ref: TitleRef, signal?: AbortSignal): Promise<TitleDetail> {
    const data = await this.get(titlePath(ref), { append_to_response: "videos,external_ids,alternative_titles", include_video_language: "en,null" }, signal);
    const base = normalizeMedia(data, ref.kind);
    if (!base || data.id !== ref.id) {
      // Seasons and episodes have their own numeric IDs. Parent identity stays canonical.
      if (ref.season === undefined || !Number.isSafeInteger(data.id)) throw new Error("TMDB returned a different title.");
    }
    const normalized = base ?? normalizeMedia({ ...data, id: ref.id }, ref.kind)!;
    return { ...normalized, ...ref,
      aliases:[...new Set<string>((data.alternative_titles?.titles??data.alternative_titles?.results??[]).filter((item:Raw)=>["US","GB","CA","AU"].includes(item.iso_3166_1)).map((item:Raw)=>String(item.title??"")))].filter(Boolean).slice(0,8),
      imdbId: /^tt\d{7,10}$/.test(data.imdb_id ?? data.external_ids?.imdb_id ?? "") ? (data.imdb_id ?? data.external_ids.imdb_id) : null,
      runtime: typeof data.runtime === "number" && data.runtime > 0 ? data.runtime : null,
      genres: Array.isArray(data.genres) ? data.genres.map((g: Raw) => String(g.name)) : [],
      clips: normalizeClips(data.videos?.results, ref),
      seasons: Array.isArray(data.seasons) ? data.seasons.map((s: Raw) => ({ number: s.season_number, name: String(s.name) })).filter((s: { number: number }) => Number.isInteger(s.number)) : [],
      episodes: Array.isArray(data.episodes) ? data.episodes.map((e: Raw) => ({ number: e.episode_number, name: String(e.name), date: String(e.air_date ?? "") })).filter((e: { number: number }) => Number.isInteger(e.number)) : [] };
  }
}

